#include <Wire.h>

void setup() {
  Wire.begin();
  Serial.begin(115200);
  Serial.println(F("Scanning I2C bus..."));

  int found = 0;
  for (byte addr = 1; addr < 127; addr++) {
    Wire.beginTransmission(addr);
    byte error = Wire.endTransmission();

    if (error == 0) {
      Serial.print(F("Found device at 0x"));
      if (addr < 16) Serial.print('0');
      Serial.print(addr, HEX);

      // Identify common devices
      if (addr == 0x3C || addr == 0x3D) Serial.print(F(" (SSD1306 OLED)"));
      if (addr == 0x76 || addr == 0x77) Serial.print(F(" (BME280 pressure)"));
      if (addr == 0x48)                 Serial.print(F(" (ADS1115 ADC or TMP75)"));
      if (addr == 0x68 || addr == 0x69) Serial.print(F(" (MPU-6050 IMU)"));
      Serial.println();
      found++;
    }
  }
  Serial.print(found); Serial.println(F(" device(s) found."));
}

// Library: Adafruit BME280 Library
// Dependency: Adafruit Unified Sensor
#include <Adafruit_BME280.h>
#include <Wire.h>

Adafruit_BME280 bme;  // uses I2C address 0x76

void setup() {
  Serial.begin(115200);
  Wire.begin();

  if (!bme.begin(0x76)) {
    Serial.println(F("Error: BME280 not found at 0x76!"));
    while (1) delay(100);
  }
  Serial.println(F("BME280 ready"));
}

void loop() {
  Serial.print(F("Temp: "));     Serial.print(bme.readTemperature(), 1); Serial.print(F("°C  "));
  Serial.print(F("Humidity: ")); Serial.print(bme.readHumidity(), 1);    Serial.print(F("%  "));
  Serial.print(F("Pressure: ")); Serial.print(bme.readPressure() / 100.0F, 1); Serial.println(F(" hPa"));
  delay(1000);
}

// SD card via SPI using the SD library
// Arduino Uno SPI pins: 11=MOSI, 12=MISO, 13=SCK, 10=CS
#include <SPI.h>
#include <SD.h>

const int SD_CS = 10;

void setup() {
  Serial.begin(115200);

  if (!SD.begin(SD_CS)) {
    Serial.println(F("SD card init failed!"));
    while (1);
  }
  Serial.println(F("SD card ready"));

  // Create/append a file
  File logFile = SD.open("log.csv", FILE_WRITE);
  if (logFile) {
    logFile.println(F("time_ms,temperature,humidity"));
    logFile.close();
    Serial.println(F("Header written"));
  }
}

void loop() {
  File logFile = SD.open("log.csv", FILE_WRITE);
  if (logFile) {
    logFile.print(millis());
    logFile.print(',');
    logFile.print(25.3);  // replace with actual sensor read
    logFile.print(',');
    logFile.println(60.1);
    logFile.close();
  }
  delay(5000);
}
